/* Flight query entrance; shared catalogue, account-scoped forms and legacy flight consumers. */
(function(root){'use strict';
let active=false,view='query';
const account=()=>String(typeof actId==='function'?actId():'main'), norm=v=>NorthHotelData.normalize(v);
function roleOptions(){return (S.contacts||[]).filter(c=>!c.deleted&&!c.blocked&&!c.isPhoneFriend).map(c=>({id:'role:'+c.id,name:c.remark||c.name}));}
function party(s=state()){return s.people||[{id:'me',name:S.me.name||'我'}];}
function companions(){const s=state();modal('<h3>选择出行方式</h3><div class="ctf-party-types"><label><input type="radio" name="ctfPartyMode" value="self" '+(party(s).length===1?'checked':'')+'>自己去</label><label><input type="radio" name="ctfPartyMode" value="together" '+(party(s).length>1?'checked':'')+'>和角色一起</label></div><div class="ctf-role-options">'+roleOptions().map(c=>'<label><input type="checkbox" onchange="NorthTravelFlight.markTogether()" value="'+esc(c.id)+'" '+(party(s).some(x=>x.id===c.id)?'checked':'')+'><span>'+esc(c.name)+'</span></label>').join('')+'</div><p>你和每位同行角色都按1位成人计入人数。选择自己去时会清除同行角色；最多选择8位角色。</p><button onclick="NorthTravelFlight.saveCompanions()">确定同行人员</button>');}
function markTogether(){const e=document.querySelector('input[name=ctfPartyMode][value=together]');if(e)e.checked=true;}
function saveCompanions(){const mode=document.querySelector('input[name=ctfPartyMode]:checked')?.value,ids=Array.from(document.querySelectorAll('.ctf-role-options input:checked')).map(x=>x.value),opts=roleOptions();if(mode==='together'&&(!ids.length||ids.length>8||ids.some(id=>!opts.some(c=>c.id===id))))return toast('请选择1—8位有效的同行角色');if(!['self','together'].includes(mode))return toast('请选择出行方式');const s=state();const people=[{id:'me',name:S.me.name||'我'},...(mode==='together'?opts.filter(c=>ids.includes(c.id)):[])];if(people.length+s.children+s.infants>9)return toast('总乘机人数不能超过9人，请先调整儿童和婴儿人数');s.people=people;s.adults=people.length;closeModal();update();}
function state(){const t=tvInit();t.flightForms=t.flightForms||{};const a=account();const s=t.flightForms[a]||(t.flightForms[a]={type:'one',cls:'economy',adults:1,children:0,infants:0,legs:[{from:typeof meHomeCity==='function'?meHomeCity()||'北京':'北京',to:'上海',date:todayStr()},{from:'上海',to:'北京',date:''}],ret:''});if(!s.people)s.people=[{id:'me',name:S.me.name||'我'}];return s;}
function cities(){return NorthHotelData.cities();}
function cityInfo(name){const q=norm(name);return cities().find(x=>norm(x.name)===q||(x.aliases||[]).some(a=>norm(a)===q));}
function routes(s=state()){return s.type==='multi'?s.legs:s.type==='return'?[s.legs[0],{from:s.legs[0].to,to:s.legs[0].from,date:s.ret}]:[s.legs[0]];}
function validDate(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return false;const t=new Date(d+'T12:00:00');return Number.isFinite(+t)&&[t.getFullYear(),String(t.getMonth()+1).padStart(2,'0'),String(t.getDate()).padStart(2,'0')].join('-')===d;}
function validate(s){const ps=party(s),known=roleOptions();if(!ps.length||ps[0].id!=='me'||new Set(ps.map(x=>x.id)).size!==ps.length||ps.slice(1).some(x=>!known.some(c=>c.id===x.id)))return '同行角色资料已变化，请重新选择';if(s.adults<ps.length)return '成人数量不能少于你和同行角色的人数';if(!['one','return','multi'].includes(s.type)||!['economy','business','first'].includes(s.cls))return '行程或舱位无效';if(!Number.isInteger(s.adults)||s.adults<1||s.adults>9||!Number.isInteger(s.children)||s.children<0||!Number.isInteger(s.infants)||s.infants<0||s.adults+s.children+s.infants>9||s.infants>s.adults)return '乘机人数需为1—9人，婴儿不能多于成人';const a=routes(s);if(a.length<1||a.length>4)return '多程最多支持4程';for(let i=0;i<a.length;i++){const l=a[i];if(!cityInfo(l.from)||!cityInfo(l.to))return '请选择已支持的出发和到达城市';if(norm(l.from)===norm(l.to))return '出发和到达不能是同一个城市';if(!validDate(l.date)||l.date<todayStr())return '请选择今天或以后的有效日期';if(i&&l.date<a[i-1].date)return '后续行程日期不能早于上一程';}return '';}
function open(){NorthTravelHome.home();active=true;view='query';render();}
function deactivate(){active=false;}
function home(){active=false;NorthTravelHome.home();}
function update(){delete state().quote;save();render();}
function type(t){if(!['one','return','multi'].includes(t))return;state().type=t;update();}
function cabin(t){if(!['economy','business','first'].includes(t))return;state().cls=t;update();}
function swap(i){const l=state().legs[i];if(!l)return;[l.from,l.to]=[l.to,l.from];update();}
function add(){const s=state();if(s.legs.length>=4)return toast('最多4程');const last=s.legs[s.legs.length-1];s.legs.push({from:last.to,to:'',date:last.date});update();}
function remove(i){const s=state();if(s.legs.length<=2)return toast('多程至少保留2程');s.legs.splice(i,1);update();}
function modal(html){openModal('<div class="ctf-dialog">'+html+'<button class="ctf-cancel" onclick="closeModal()">取消</button></div>');const p=document.getElementById('modalSheet')||document.getElementById('previewDialog');if(p)p.classList.add('ctg-white-sheet');}
let pick={i:0,which:'from'};
function options(q){q=String(q||'').trim().slice(0,60);const a=cities().filter(c=>!q||norm([c.name,c.country,...(c.aliases||[])].join(' ')).includes(norm(q)));const countries=NorthHotelData.countries.filter(c=>!q||norm(c.slice(0,3).join(' ')).includes(norm(q)));return '<h4>国家／地区（点击后选择城市）</h4><div class="ctf-options">'+countries.map(c=>'<button data-country="'+esc(c[0])+'" onclick="NorthTravelFlight.filterCountry(this.dataset.country)">'+esc(c[0])+'</button>').join('')+'</div><h4>城市</h4><div class="ctf-options">'+a.map(c=>'<button data-city="'+esc(c.name)+'" onclick="NorthTravelFlight.chooseCity(this.dataset.city)">'+esc(c.name)+'<small>'+esc(c.country)+'</small></button>').join('')+'</div>'+(!a.length?'<p>没有匹配的城市，请搜索国家或换一个城市名称。</p>':'');}
function city(i,which){if(!state().legs[i]||!['from','to'].includes(which))return;pick={i,which};modal('<h3>选择'+(which==='from'?'出发':'到达')+'城市</h3><input id="ctfCitySearch" type="search" placeholder="搜索国家、城市或地区" oninput="NorthTravelFlight.filterCity(this.value)"><div id="ctfCityOptions" class="ctf-city-options">'+options('')+'</div>');}
function filterCity(q){const e=document.getElementById('ctfCityOptions');if(e)e.innerHTML=options(q);}
function filterCountry(q){document.getElementById('ctfCitySearch').value=q;filterCity(q);}
function chooseCity(n){const c=cityInfo(n),l=state().legs[pick.i];if(!c||!l)return;l[pick.which]=c.name;closeModal();update();}
function dates(){const s=state();modal('<h3>选择出行日期</h3>'+routes(s).map((l,i)=>'<label>'+(s.type==='return'?(i?'返程日期':'出发日期'):'第'+(i+1)+'程出发日期')+'<input type="date" id="ctfDate'+i+'" min="'+todayStr()+'" value="'+esc(l.date||'')+'"></label>').join('')+'<button onclick="NorthTravelFlight.saveDates()">确定日期</button>');}
function saveDates(){const s=state(),a=routes(s),ds=a.map((_,i)=>document.getElementById('ctfDate'+i).value);if(ds.some((d,i)=>!validDate(d)||d<todayStr()||i&&d<ds[i-1]))return toast('日期必须有效，后续日期不能早于上一程');s.legs[0].date=ds[0];if(s.type==='return')s.ret=ds[1];if(s.type==='multi')s.legs.forEach((l,i)=>l.date=ds[i]);closeModal();update();}
function people(){const s=state();modal('<h3>乘机人数</h3>'+[['adults','成人',1],['children','儿童',0],['infants','婴儿',0]].map(([k,n,min])=>'<label>'+n+'<input id="ctf-'+k+'" type="number" min="'+min+'" max="9" step="1" value="'+s[k]+'"></label>').join('')+'<p>至少1位成人；总人数最多9人，每位成人最多携带1位婴儿。模拟查询不代表真实票价或余票。</p><button onclick="NorthTravelFlight.savePeople()">确定人数</button>');}
function savePeople(){const s=state(),p=Object.fromEntries(['adults','children','infants'].map(k=>[k,Number(document.getElementById('ctf-'+k).value)]));if(!Number.isInteger(p.adults)||p.adults<1||!Number.isInteger(p.children)||p.children<0||!Number.isInteger(p.infants)||p.infants<0||p.adults+p.children+p.infants>9||p.infants>p.adults||p.adults<party(s).length)return toast('请检查人数：最多9人，婴儿不能多于成人，成人不能少于同行人数');Object.assign(s,p);closeModal();update();}
function md(d){if(!d)return '选择日期';return (+d.slice(5,7))+'月'+(+d.slice(8,10))+'日';}
function relative(d){const n=new Date(d+'T12:00:00')-new Date(todayStr()+'T12:00:00');return n===0?'今天':n===86400000?'明天':n===172800000?'后天':'';}
function routeHTML(l,i,s){return '<div class="ctf-leg">'+(s.type==='multi'?'<div class="ctf-leg-label">第'+(i+1)+'程'+(s.legs.length>2?'<button onclick="NorthTravelFlight.remove('+i+')">删除</button>':'')+'</div>':'')+'<div class="ctf-route"><button aria-label="第'+(i+1)+'程出发城市" onclick="NorthTravelFlight.city('+i+',\'from\')">'+esc(l.from||'出发城市')+'</button><button class="ctf-swap" aria-label="交换第'+(i+1)+'程城市" onclick="NorthTravelFlight.swap('+i+')">⇄</button><button aria-label="第'+(i+1)+'程到达城市" onclick="NorthTravelFlight.city('+i+',\'to\')">'+esc(l.to||'到达城市')+'</button></div><button class="ctf-date" onclick="NorthTravelFlight.dates()"><b>'+md(l.date)+'</b><span>'+relative(l.date)+'</span>'+(s.type==='return'?'<em>—</em><b>'+md(s.ret)+'</b><span>'+relative(s.ret)+'</span>':'')+'</button></div>';}
function query(){const s=state(),error=validate(s);if(error)return toast(error);s.quote={account:account(),type:s.type,cls:s.cls,adults:s.adults,children:s.children,infants:s.infants,people:party(s).map(x=>({...x})),legs:routes(s).map(l=>({...l})),ts:Date.now()};NorthFlightBooking.startQuote(s.quote);save();view='results';render();}
function edit(){view='query';render();}
function results(){return NorthFlightBooking.render();}
function showResults(){if(typeof NorthTravelConcert!=='undefined')NorthTravelConcert.deactivate();if(typeof NorthTravelTrain!=='undefined')NorthTravelTrain.deactivate();active=true;view='results';render();}
function legacyResults(i){NorthFlightBooking.setLeg(i);}

function renderQuery(){const s=state();return '<div class="ctf-app"><main class="ctf-scroll travel-scroll"><section class="ctf-hero"><button class="ctf-back" aria-label="返回旅行首页" onclick="NorthTravelFlight.home()"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M15.5 5 8.5 12 15.5 19" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button><span class="ctf-hero-plane">'+NorthTravelHome.icon('plane')+'</span><div class="ctf-brand">'+NorthTravelHome.icon('dolphin')+' 小鱼旅行</div><h2>浪漫秋日 · 飞向美好</h2><p>下一站，去见想见的风景</p><div class="ctf-skyline"></div></section><section class="ctf-card"><h1>机票</h1><div class="ctf-trip-types">'+[['one','单程'],['return','往返'],['multi','多程']].map(([k,n])=>'<button class="'+(s.type===k?'selected':'')+'" onclick="NorthTravelFlight.type(\''+k+'\')">'+n+'</button>').join('')+'</div>'+((s.type==='multi'?s.legs:[s.legs[0]]).map((l,i)=>routeHTML(l,i,s)).join(''))+(s.type==='multi'?'<button class="ctf-add" onclick="NorthTravelFlight.add()">＋ 添加一程</button>':'')+'<div class="ctf-details"><div class="ctf-cabin">'+[['economy','经济舱'],['business','公务 / 头等舱']].map(([k,n])=>'<button class="'+((k==='economy'?s.cls===k:s.cls!=='economy')?'selected':'')+'" onclick="NorthTravelFlight.'+(k==='economy'?'cabin(\'economy\')':'premium()')+'">'+n+'</button>').join('')+'</div><button class="ctf-passengers" onclick="NorthTravelFlight.people()">'+s.adults+'成人'+s.children+'儿童'+s.infants+'婴儿⌄</button></div><button class="ctf-companions" onclick="NorthTravelFlight.companions()"><span>出行人员</span><b>'+esc(party(s).length>1?party(s).map(x=>x.name).join('、'):'自己去')+'</b><i>›</i></button><button class="ctf-query" aria-label="查询航班" onclick="NorthTravelFlight.query()"><span class="ctf-query-fish">'+NorthTravelHome.icon('dolphin')+'</span>查 询<span class="ctf-balloons">◌</span></button><p class="ctf-note">小手机内模拟查询与预订</p></section><div class="ctf-orders-wrap"><button class="ctf-orders-entry" onclick="NorthFlightBooking.orders()"><b>我的机票订单</b><span>›</span></button></div></main></div>';}
function premium(){modal('<h3>选择舱位</h3><button onclick="NorthTravelFlight.cabin(\'business\');closeModal()">公务舱</button><button onclick="NorthTravelFlight.cabin(\'first\');closeModal()">头等舱</button>');}
function roleGuard(c,city,date,gift){if(!c||c.deleted||c.blocked||c.isPhoneFriend)return {error:'角色不可用'};const target=cityInfo(city),from=cityInfo(gift?meHomeCity()||'苏州':charHomeCity(c));if(!target||!from||norm(target.name)===norm(from.name))return {error:'请确认支持的出发及到达城市'};if(!/^(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\s*月\s*\d{1,2}\s*日?)$/.test(String(date||'').trim()))return {error:'请提供明确出发日期'};const d=tvNormDate(date);if(!validDate(d)||d<todayStr())return {error:'机票日期无效或已经过去'};const cls=gift?'economy':'business',price=tvPrice(from.name,target.name,cls),m=tvHotelRoleMoney(c);if(!Number.isFinite(price)||price<=0||!m||!Number.isFinite(m.balance))return {error:'角色自己的银行余额不足或未设置'};return {from:from.name,to:target.name,date:d,cls,price,m};}
function roleLegacy(c,city,date,gift){if(!gift){const from=charHomeCity(c),mine=meHomeCity();if(from&&mine&&tvSameCity(city,from)&&!tvSameCity(city,mine))city=mine;}const g=roleGuard(c,city,date,gift);if(g.error){toast('机票未预订：'+g.error);return false;}return NorthFlightBooking.roleDirect(c,g.from,g.to,g.date,gift?'经济舱':'公务舱',gift?'给你':'我自己');const t=tvInit(),key=JSON.stringify([account(),c.id,g.from,g.to,g.date,gift?'gift':'meet']);if(t.trips.some(x=>x.flightKey===key&&x.status==='upcoming'))return true;if(g.m.balance<g.price){toast('机票未预订：角色自己的银行余额不足');return false;}const d=S.spy?.[c.id],seed=(Date.now()+g.to.length+g.from.length)|0,tm=tvLegTimes(g.from,g.to,seed),trip={id:uid(),accountId:account(),flightKey:key,cid:c.id,from:g.from,to:g.to,date:g.date,ret:'',cls:g.cls,pax:1,by:'ta',meet:!gift,flier:gift?'me':'ta',payer:'ta',fundingSource:g.m.source,no:tvFlightNo(seed),dep:tm.dep,arr:tm.arr,price:g.price,status:'upcoming',ts:Date.now()};if(g.m.source==='roleWallet')c.wallet=+(g.m.balance-g.price).toFixed(2);else if(g.m.source==='roleBank'&&d)d.balance=+(g.m.balance-g.price).toFixed(2);else return false;if(d){d.wallet=d.wallet||[];d.wallet.unshift({item:'机票预订：'+g.from+'→'+g.to,amount:-g.price,when:g.date,tripId:trip.id});d.wallet=d.wallet.slice(0,40);}t.trips.push(trip);msgs(c.id).push({role:'assistant',type:'ticket',trip,id:uid(),time:Date.now()});save();if(cur().p==='chat'&&cur().id===c.id)render();return true;}
function cityFallback(n){const c=cityInfo(n);return c?{n:c.name,c:'---',i:c.country==='中国'?0:1,g:c.region||'其他',r:c.country}:null;}
root.NorthTravelFlight={active:()=>active,modal,showResults,open,deactivate,home,render:()=>view==='results'?results():renderQuery(),state,cities,routes,validate,companions,saveCompanions,party,markTogether,query,type,cabin,swap,add,remove,city,filterCity,filterCountry,chooseCity,dates,saveDates,people,savePeople,premium,edit,legacyResults,roleLegacy,cityFallback};
})(globalThis);
